declare(strict_types=1);
require_once __DIR__.'/receipt-files.php';require_once __DIR__.'/board-report.php';
function mkt_schema(PDO $db): void {$db->exec("CREATE TABLE IF NOT EXISTS marketing_imports(id INTEGER PRIMARY KEY AUTOINCREMENT,token TEXT UNIQUE NOT NULL,name TEXT NOT NULL,path TEXT NOT NULL,extension TEXT NOT NULL,data_date TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',config TEXT NOT NULL DEFAULT '{}',summary TEXT NOT NULL DEFAULT '{}');CREATE TABLE IF NOT EXISTS marketing_rows(id INTEGER PRIMARY KEY AUTOINCREMENT,row_key TEXT UNIQUE NOT NULL,scope_key TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,import_id INTEGER NOT NULL,day TEXT NOT NULL,account TEXT NOT NULL,campaign TEXT NOT NULL,campaign_id TEXT NOT NULL,ad TEXT NOT NULL,ad_id TEXT NOT NULL,sku TEXT NOT NULL,gender TEXT NOT NULL,spend REAL NOT NULL,fee REAL,orders REAL,source_row INTEGER NOT NULL,updated_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS marketing_rows_date ON marketing_rows(day,sku,gender);CREATE TABLE IF NOT EXISTS marketing_policy(id INTEGER PRIMARY KEY CHECK(id=1),cost_mode TEXT NOT NULL,fee_percent REAL NOT NULL,order_source TEXT NOT NULL)");}
function mkt_number($value): ?float {
 $text=trim((string)$value);if($text===''||in_array($text,['—','–','-'],true))return null;$text=preg_replace('/(?:VND|VNĐ|USD|₫|đ|\$|\s|\x{00a0})/iu','',$text);if(preg_match('/^\((.*)\)$/D',$text,$m))$text='-'.$m[1];
 if(str_contains($text,',')&&str_contains($text,'.')){$decimal=strrpos($text,',')>strrpos($text,'.')?',':'.';$text=str_replace($decimal===','?'.':',','',$text);if($decimal===',')$text=str_replace(',','.',$text);}elseif(preg_match('/^-?\d{1,3}(?:[.,]\d{3})+$/D',$text))$text=str_replace([',','.'],'',$text);else $text=str_replace(',','.',$text);
 if(!is_numeric($text))return null;$number=(float)$text;return is_finite($number)&&abs($number)<=1000000000000?$number:null;
}
function mkt_day($value,string $fallback): ?string {
 $value=trim((string)$value);if($value==='')return $fallback;
 if(is_numeric($value)&&(float)$value>=20000&&(float)$value<=100000)return (new DateTimeImmutable('1899-12-30'))->modify('+'.(int)(float)$value.' days')->format('Y-m-d');
 foreach(['!Y-m-d','!d/m/Y','!d-m-Y','!d.m.Y','!Y-m-d H:i:s','!d/m/Y H:i:s'] as $format){$day=DateTimeImmutable::createFromFormat($format,$value);$errors=DateTimeImmutable::getLastErrors();if($day&&(!$errors||(!$errors['warning_count']&&!$errors['error_count'])))return $day->format('Y-m-d');}return null;
}
function mkt_text_table(string $text): array {$lines=preg_split('/\r\n|\n|\r/',$text);$probe=implode("\n",array_slice($lines,0,20));$separator=str_contains($probe,"\t")?"\t":(substr_count($probe,';')>substr_count($probe,',')?';':',');$rows=[];foreach($lines as $line)if(trim($line)!==''){$cells=str_getcsv($line,$separator);if(count($cells)>512||count($rows)>=50000)throw new RuntimeException('Bảng quá lớn.',413);$rows[]=$cells;}if(array_sum(array_map('count',$rows))>500000)throw new RuntimeException('Bảng quá lớn.',413);return ['Dữ liệu dán'=>$rows];}
function mkt_tables(array $upload): array {return $upload['extension']==='tsv'?mkt_text_table(file_get_contents($upload['path'])):receipt_file_tables($upload['path'],$upload['extension']);}
function mkt_columns(array $headers): array {
 $map=[];$aliases=['end_day'=>['KET THUC BAO CAO','REPORTING ENDS'],'day'=>['NGAY','DATE','DAY','NGAY BAO CAO','REPORTING STARTS','BAT DAU BAO CAO'],'spend'=>['CHI TIEU','SO TIEN DA CHI TIEU','AMOUNT SPENT','SPEND','CHI PHI QUANG CAO'],'fee'=>['PHI KHAC','PHU PHI','EXTRA FEE'],'orders'=>['SO DON','DON HANG','LUOT MUA','PURCHASES','WEBSITE PURCHASES','LUOT MUA HANG TREN TRANG WEB'],'campaign'=>['TEN CHIEN DICH','CHIEN DICH','CAMPAIGN NAME','CAMPAIGN'],'campaign_id'=>['ID CHIEN DICH','CAMPAIGN ID'],'ad'=>['TEN QUANG CAO','AD NAME'],'ad_id'=>['ID QUANG CAO','AD ID'],'sku'=>['MA SAN PHAM','MA SP','SKU','SAN PHAM'],'gender'=>['GIOI TINH','NHOM','NAM/NU'],'account'=>['TAI KHOAN','TEN TAI KHOAN','ACCOUNT NAME','ACCOUNT']];
 foreach($headers as $c=>$h){$h=report_fold((string)$h);foreach($aliases as $key=>$names)foreach($names as $name)if(($h===$name||preg_match('/^'.preg_quote($name,'/').'\s*\((?:VND|VNĐ|USD|Đ)\)$/u',$h))&&!isset($map[$key])){$map[$key]=(int)$c;break;}}return $map;
}
function mkt_preview(array $upload): array {$tables=mkt_tables($upload);$result=[];foreach($tables as $name=>$rows){$best=null;foreach($rows as $r=>$cells){if((int)$r>30)break;$map=mkt_columns($cells);if(isset($map['spend'])&&(isset($map['campaign'])||isset($map['campaign_id']))){$best=['headerRow'=>(int)$r,'headers'=>$cells,'map'=>$map];break;}}if(!$best){$r=array_key_first($rows);$best=['headerRow'=>(int)($r??0),'headers'=>$rows[$r]??[],'map'=>mkt_columns($rows[$r]??[])];}$best['sheet']=$name;$best['rowCount']=count($rows);$best['sample']=array_slice(array_values(array_filter($rows,static fn($r)=>$r>$best['headerRow'],ARRAY_FILTER_USE_KEY)),0,5);$width=0;foreach($best['sample'] as $sample)$width=max($width,count($sample));for($c=0;$c<$width;$c++)$best['headers'][$c]??='Cột '.($c+1);$result[]=$best;}return $result;}
function mkt_parse(array $tables,array $config,array $catalog): array {
 $rows=$tables[$config['sheet']??'']??null;if(!$rows)throw new RuntimeException('Chọn sheet dữ liệu.',400);$map=$config['map']??[];if(!isset($map['spend'])||(!isset($map['campaign'])&&!isset($map['campaign_id'])))throw new RuntimeException('Cần chọn cột chi tiêu và chiến dịch.',400);$fallback=(string)($config['date']??'');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$fallback)||mkt_day($fallback,'')!==$fallback)throw new RuntimeException('Chọn ngày dữ liệu.',400);$exchange=(float)($config['exchange']??1);if(!is_finite($exchange)||$exchange<=0||$exchange>1000000000)throw new RuntimeException('Tỷ giá quy đổi không hợp lệ.',400);
 $parsed=[];$issues=[];$errors=[];$moneyHeader=(string)($rows[(int)($config['headerRow']??0)][(int)$map['spend']]??'');if(($config['currency']??'VND')==='VND'&&(preg_match('/USD|\$/i',$moneyHeader)||$exchange!==1.0))throw new RuntimeException('Chọn đơn vị ngoại tệ và tỷ giá phù hợp.',400);$skus=array_keys($catalog);usort($skus,static fn($a,$b)=>strlen($b)<=>strlen($a));$pattern=$skus?'/(?<![A-Z0-9])('.implode('|',array_map(static fn($s)=>preg_quote($s,'/'),$skus)).')(?![A-Z0-9])/i':'/(?!) /';
 foreach($rows as $r=>$cells){if((int)$r<=(int)($config['headerRow']??0))continue;if(!array_filter($cells,static fn($v)=>trim((string)$v)!==''))continue;$get=static fn($key)=>isset($map[$key])?trim((string)($cells[(int)$map[$key]]??'')):'';$campaign=$get('campaign');$campaignId=$get('campaign_id');if($campaign===''&&$campaignId==='')continue;if(preg_match('/^(TỔNG(?:\s|$)|TOTAL(?:\s|$)|RESULTS FROM|KẾT QUẢ TỪ)/iu',$campaign))continue;
  if(($config['currency']??'VND')==='VND'&&preg_match('/USD|\$/i',$get('spend'))){$errors[]=['row'=>(int)$r+1,'text'=>'Chi tiêu có đơn vị ngoại tệ. Chọn tỷ giá trước khi lưu.'];continue;}$day=mkt_day($get('day'),$fallback);if($get('end_day')!==''&&mkt_day($get('end_day'),$fallback)!==$day){$errors[]=['row'=>(int)$r+1,'text'=>'Chi tiêu gộp nhiều ngày. Chọn phân tích theo từng ngày trên màn hình quảng cáo rồi chuyển lại.'];continue;}$spend=mkt_number($get('spend'));$fee=mkt_number($get('fee'));$orders=mkt_number($get('orders'));$account=$get('account')?:trim((string)($config['account']??''));if(!$day||$spend===null||$spend<0||($get('fee')!==''&&$fee===null)||$account===''){$errors[]=['row'=>(int)$r+1,'text'=>!$day?'Ngày không đọc được':($account===''?'Thiếu tài khoản / nguồn dữ liệu':'Chi tiêu hoặc phụ phí không đọc được')];continue;}if($orders!==null&&$orders<0){$errors[]=['row'=>(int)$r+1,'text'=>'Số đơn không được âm'];continue;}
  $explicit=mb_strtoupper($get('sku'),'UTF-8');$sku=$explicit;$inferred=[];if($sku===''){preg_match_all($pattern,$campaign.' '.$get('ad'),$matches);$inferred=array_values(array_unique(array_map('strtoupper',$matches[1]??[])));if(count($inferred)===1)$sku=$inferred[0];}if($sku===''&&!$inferred)$sku=mb_strtoupper(trim((string)($config['default_sku']??'')),'UTF-8');if($sku!==''&&!isset($catalog[$sku])){$issues[]=['row'=>(int)$r+1,'text'=>'Mã chưa có trong danh mục: '.$sku];$sku='';}
  $gender=$sku!==''?($catalog[$sku]['gender']??''):'';$sourceGender=report_fold($get('gender'));if($gender==='')$gender=$sourceGender==='NAM'?'Nam':($sourceGender==='NU'?'Nữ':'');if($gender===''&&$inferred){$groups=array_values(array_unique(array_filter(array_map(static fn($s)=>$catalog[$s]['gender']??'',$inferred))));if(count($groups)===1)$gender=$groups[0];}if($sku==='')$issues[]=['row'=>(int)$r+1,'text'=>count($inferred)>1?'Có nhiều mã trong tên; chưa phân bổ chi tiêu theo mã':'Chưa xác định mã sản phẩm'];
  $ad=$get('ad');$adId=$get('ad_id');$scope=hash('sha256',json_encode([$day,report_fold($account),$campaignId?:report_fold($campaign),$adId?:report_fold($ad)],JSON_UNESCAPED_UNICODE));$rowKey=hash('sha256',$scope.'|'.$sku.'|'.$gender);$value=['row_key'=>$rowKey,'scope_key'=>$scope,'day'=>$day,'account'=>$account,'campaign'=>$campaign?:$campaignId,'campaign_id'=>$campaignId,'ad'=>$ad,'ad_id'=>$adId,'sku'=>$sku,'gender'=>$gender,'spend'=>$spend*$exchange,'fee'=>$fee===null?null:$fee*$exchange,'orders'=>$orders,'source_row'=>(int)$r+1];
  if(isset($parsed[$rowKey])){$parsed[$rowKey]['spend']+=$value['spend'];$parsed[$rowKey]['fee']=$fee===null||$parsed[$rowKey]['fee']===null?null:$parsed[$rowKey]['fee']+$value['fee'];$parsed[$rowKey]['orders']=$orders===null||$parsed[$rowKey]['orders']===null?null:$parsed[$rowKey]['orders']+$orders;}else $parsed[$rowKey]=$value;
  if(count($parsed)>10000)throw new RuntimeException('Mỗi lần nhập tối đa 10.000 dòng chiến dịch.',413);
 }return ['rows'=>array_values($parsed),'issues'=>$issues,'errors'=>$errors,'spend'=>array_sum(array_column($parsed,'spend'))];
}
function mkt_import(PDO $db,int $id,array $config,array $user): array {
 $q=$db->prepare('SELECT * FROM marketing_imports WHERE id=?');$q->execute([$id]);$source=$q->fetch();if(!$source)throw new RuntimeException('Không tìm thấy nguồn dữ liệu.',404);if($source['status']==='applied')return json_decode($source['summary'],true,512,JSON_THROW_ON_ERROR);$data=mkt_parse(mkt_tables($source),$config,board_catalog($db));if($data['errors'])throw new RuntimeException('Cần sửa dòng '.$data['errors'][0]['row'].': '.$data['errors'][0]['text'],400);if(!$data['rows'])throw new RuntimeException('Chưa có dòng chiến dịch hợp lệ.',400);
 $db->exec('BEGIN IMMEDIATE');try{
  $q=$db->prepare('SELECT status,summary FROM marketing_imports WHERE id=?');$q->execute([$id]);$check=$q->fetch();if($check['status']==='applied'){$db->exec('COMMIT');return json_decode($check['summary'],true,512,JSON_THROW_ON_ERROR);}
  $now=gmdate('c');$find=$db->prepare('SELECT id FROM marketing_rows WHERE row_key=?');$retire=$db->prepare('UPDATE marketing_rows SET active=0 WHERE scope_key=?');$scopes=[];
  foreach($data['rows'] as $row)$scopes[$row['scope_key']]=true;foreach(array_keys($scopes) as $scope)$retire->execute([$scope]);
  $save=$db->prepare('INSERT INTO marketing_rows(row_key,scope_key,active,import_id,day,account,campaign,campaign_id,ad,ad_id,sku,gender,spend,fee,orders,source_row,updated_at) VALUES(?,?,1,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(row_key) DO UPDATE SET active=1,import_id=excluded.import_id,campaign=excluded.campaign,campaign_id=excluded.campaign_id,ad=excluded.ad,ad_id=excluded.ad_id,sku=excluded.sku,gender=excluded.gender,spend=excluded.spend,fee=excluded.fee,orders=excluded.orders,source_row=excluded.source_row,updated_at=excluded.updated_at');
  $added=0;$updated=0;foreach($data['rows'] as $row){$find->execute([$row['row_key']]);if($find->fetchColumn())$updated++;else $added++;$save->execute([$row['row_key'],$row['scope_key'],$id,$row['day'],$row['account'],$row['campaign'],$row['campaign_id'],$row['ad'],$row['ad_id'],$row['sku'],$row['gender'],$row['spend'],$row['fee'],$row['orders'],$row['source_row'],$now]);}
  $summary=['added'=>$added,'updated'=>$updated,'spend'=>$data['spend'],'issues'=>$data['issues']];$db->prepare('UPDATE marketing_imports SET status=?,config=?,summary=? WHERE id=?')->execute(['applied',json_encode($config,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),json_encode($summary,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$id]);people_audit('marketing_import',(string)$id,$summary,$db);$db->exec('COMMIT');return $summary;
 }catch(Throwable $e){$db->exec('ROLLBACK');throw $e;}
}

function mkt_policy(PDO $db): ?array {return ['cost_mode'=>'spend_only','fee_percent'=>0.0,'order_source'=>'board'];}
function mkt_order_counts(PDO $db,string $source,array $range,string $sku): array {
 $result=['total'=>0,'Nam'=>0,'Nữ'=>0,'products'=>[]];$catalog=board_catalog($db);
 $add=static function(array $skus,array $genders)use(&$result,$sku){$skus=array_values(array_unique(array_filter($skus)));if($sku!==''&&!in_array($sku,$skus,true))return;$result['total']++;foreach(array_unique($genders) as $g)if(isset($result[$g]))$result[$g]++;foreach($skus as $s)$result['products'][$s]=($result['products'][$s]??0)+1;};
 if($source==='board'){foreach(board_rows($db,$catalog)['rows'] as $row)if($row['date']>=$range['from']&&$row['date']<=$range['to'])$add(array_column($row['items'],'sku'),[$row['gender']]);}
 elseif($source==='web'){$zone=new DateTimeZone('Asia/Ho_Chi_Minh');$utc=new DateTimeZone('UTC');$from=(new DateTimeImmutable($range['from'],$zone))->setTimezone($utc)->format('Y-m-d\TH:i:s\Z');$to=(new DateTimeImmutable($range['to'],$zone))->modify('+1 day')->setTimezone($utc)->format('Y-m-d\TH:i:s\Z');$q=$db->prepare('SELECT * FROM orders o WHERE created_at>=? AND created_at<? AND NOT EXISTS(SELECT 1 FROM order_admin_trash t WHERE t.code=o.code)');$q->execute([$from,$to]);foreach($q as $raw){$order=admin_order($raw);$codes=array_column($order['items'],'sku');$genders=[];foreach($codes as $code)if(isset($catalog[$code]))$genders[]=$catalog[$code]['gender'];$add($codes,$genders);}}
 return $result;
}
function mkt_report(PDO $db,array $input): array {
 $catalog=board_catalog($db);$range=report_range($input);$sku=mb_strtoupper(trim((string)($input['sku']??'')),'UTF-8');$query=report_fold(trim((string)($input['campaign']??'')));$q=$db->prepare('SELECT * FROM marketing_rows WHERE active=1 AND day>=? AND day<=?'.($sku!==''?' AND sku=?':'').' ORDER BY day LIMIT 100001');$q->execute($sku!==''?[$range['from'],$range['to'],$sku]:[$range['from'],$range['to']]);$rows=$q->fetchAll();if(count($rows)>100000)throw new RuntimeException('Thu hẹp khoảng ngày để xem tối đa 100.000 dòng MKT.',413);if($query!=='')$rows=array_values(array_filter($rows,static fn($r)=>str_contains(report_fold($r['campaign'].' '.$r['account']),$query)));$policy=mkt_policy($db);
 $empty=static fn()=>['spend'=>0.0,'fees'=>0.0,'feeComplete'=>true,'adsOrders'=>0.0,'ordersComplete'=>true,'rows'=>0];$groups=['total'=>$empty(),'Nam'=>$empty(),'Nữ'=>$empty(),'unclassified'=>$empty()];$products=[];$campaigns=[];$daily=[];
 $sum=static function(array &$target,array $r){$target['spend']+=(float)$r['spend'];$target['fees']+=(float)($r['fee']??0);$target['feeComplete']=$target['feeComplete']&&$r['fee']!==null;$target['adsOrders']+=(float)($r['orders']??0);$target['ordersComplete']=$target['ordersComplete']&&$r['orders']!==null;$target['rows']++;};
 foreach($rows as $r){$sum($groups['total'],$r);$sum($groups[in_array($r['gender'],['Nam','Nữ'],true)?$r['gender']:'unclassified'],$r);$key=$r['sku'];$products[$key]??=['sku'=>$key,'name'=>($catalog[$r['sku']]['name']??($r['sku']?:'Chưa xác định mã'))]+$empty();$sum($products[$key],$r);$c=$r['account'].'|'.($r['campaign_id']?:$r['campaign']);$campaigns[$c]??=['account'=>$r['account'],'campaign'=>$r['campaign'],'campaign_id'=>$r['campaign_id']]+$empty();$sum($campaigns[$c],$r);$daily[$r['day']]??=['day'=>$r['day']]+$empty();$sum($daily[$r['day']],$r);}
 $unattributed=$query!==''&&$policy&&$policy['order_source']!=='ads';$counts=$policy&&$policy['order_source']!=='ads'&&!$unattributed?mkt_order_counts($db,$policy['order_source'],$range,$sku):null;
 $finish=static function(array $item,?float $orders)use($policy){$cost=null;if($policy&&($policy['cost_mode']==='spend_only'||$item['feeComplete']))$cost=$item['spend']*(1+$policy['fee_percent']/100)+($policy['cost_mode']==='spend_plus_fees'?$item['fees']:0);$item['cost']=$cost;$item['orders']=$orders;$item['cpa']=$cost!==null&&$orders!==null&&$orders>0?$cost/$orders:null;return $item;};
 foreach($groups as $key=>&$item){$orders=$counts?($key==='total'?(float)$counts['total']:(in_array($key,['Nam','Nữ'],true)?(float)$counts[$key]:null)):($policy&&!$unattributed&&$item['ordersComplete']?$item['adsOrders']:null);$item=$finish($item,$orders);}unset($item);
 foreach($products as $key=>&$item)$item=$finish($item,$counts?($key!==''?(float)($counts['products'][$key]??0):null):($policy&&!$unattributed&&$item['ordersComplete']?$item['adsOrders']:null));unset($item);
 foreach($campaigns as &$item)$item=$finish($item,$item['ordersComplete']?$item['adsOrders']:null);unset($item);foreach($daily as &$item)$item=$finish($item,$item['ordersComplete']?$item['adsOrders']:null);unset($item);
 usort($products,static fn($a,$b)=>$b['spend']<=>$a['spend']);usort($campaigns,static fn($a,$b)=>$b['spend']<=>$a['spend']);
 return ['range'=>$range,'policy'=>$policy,'hasData'=>(bool)$rows,'groups'=>$groups,'products'=>array_values($products),'campaigns'=>array_values($campaigns),'daily'=>array_values($daily),'catalog'=>array_values($catalog),'attributionNotice'=>$unattributed?'ĐƠN WEB và BẢNG ĐƠN chưa có liên kết chiến dịch. Khi lọc chiến dịch, chi phí/đơn chỉ hiển thị ở bảng chiến dịch nếu có số đơn QC.':''];
}
